import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt(), weeks = r.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = r.nextLong();
        final long INF = Long.MAX_VALUE / 4;
        long[] prev = new long[n + 1];
        Arrays.fill(prev, INF);
        prev[0] = 0;
        for (int w = 1; w <= weeks; w++) {
            long[] cur = new long[n + 1];
            Arrays.fill(cur, INF);
            for (int i = w; i <= n; i++) {
                long high = 0;
                for (int j = i - 1; j >= w - 1; j--) {  // last week covers a[j..i-1]
                    high = Math.max(high, a[j]);
                    cur[i] = Math.min(cur[i], prev[j] + high);
                }
            }
            prev = cur;
        }
        System.out.println(prev[n]);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

